pub static MONSTER_BOOKS: crate::rules_core::rules_catalog::Derived<MonsterBook> =
    crate::rules_core::rules_catalog::Derived::new(monster_books_from_package);

fn monster_books_from_package() -> Vec<MonsterBook> {
    use crate::rules_core::rules_catalog::rows;
    use crate::rules_core::rules_data_package::MonsterBookIndexRow;
    rows::<MonsterBookIndexRow>("monster_chassis/MONSTER_BOOKS")
        .iter()
        .map(|book| MonsterBook {
            corpus_book: book.corpus_book,
            monsters: if book.monsters.is_empty() {
                &[]
            } else {
                rows::<MonsterStatBlock>(book.monsters)
            },
            monster_abilities: if book.monster_abilities.is_empty() {
                &[]
            } else {
                rows::<MonsterAbilityRecord>(book.monster_abilities)
            },
            cross_table_owner_names: book.cross_table_owner_names,
        })
        .collect()
}
// MONSTER_BOOK_REGISTRY: the Pathfinder book list is MONSTER_BOOKS (package-backed); no other system registers a monster book yet.;
pub fn monster_book(corpus_book: &str) -> Option<&'static MonsterBook> {
    MONSTER_BOOKS
        .iter()
        .find(|book| book.corpus_book == corpus_book)
}
